  'g3.check': 'ꯐꯥꯏꯜ ꯇꯧꯗꯨꯅ ꯃꯃꯥꯡꯗ ꯃꯁꯤꯁꯤꯡ ꯌꯦꯡꯕꯤꯌꯨ', 'g3.h.pay': 'ꯇꯦꯛꯁ ꯄꯦꯃꯦꯟꯠ (ꯇꯦꯕꯜ 6.1)', 'g3.h.cf': 'ꯏꯅꯄꯨꯠ ꯇꯦꯛꯁ ꯀ꯭ꯔꯦꯗꯤꯠ', 'g3.h.32': '3.2 ꯔꯦꯖꯤꯁ꯭ꯇꯔ ꯇꯧꯗꯕ ꯃꯤꯁꯤꯡꯗ ꯁ꯭ꯇꯦꯠ ꯑꯅꯤꯒꯤ ꯃꯔꯛꯇ ꯁꯞꯂꯥꯏ',
  'g3.p.liab': 'ꯄꯤꯒꯗꯕ ꯇꯦꯛꯁ (ꯐꯣꯔꯋꯥꯔꯗ ꯆꯥꯔꯖ)', 'g3.p.byigst': 'IGST ꯀ꯭ꯔꯦꯗꯤꯠꯅ ꯄꯤꯈꯤ', 'g3.p.bycgst': 'CGST ꯀ꯭ꯔꯦꯗꯤꯠꯅ ꯄꯤꯈꯤ', 'g3.p.bysgst': 'SGST/UTGST ꯀ꯭ꯔꯦꯗꯤꯠꯅ ꯄꯤꯈꯤ', 'g3.p.bycess': 'ꯁꯦꯁ ꯀ꯭ꯔꯦꯗꯤꯠꯅ ꯄꯤꯈꯤ',
  'g3.p.left': 'ꯀ꯭ꯔꯦꯗꯤꯠ ꯃꯇꯨꯡꯗꯁꯨ ꯄꯤꯒꯗꯕ ꯂꯦꯃꯍꯧꯔꯤ', 'g3.p.rcm': 'ꯔꯤꯚꯔꯁ ꯆꯥꯔꯖ ꯇꯦꯛꯁ', 'g3.p.int': 'ꯏꯟꯇꯔꯦꯁ꯭ꯠ ꯑꯃꯁꯨꯡ ꯂꯦꯠ ꯐꯤ', 'g3.p.cash': 'ꯀꯦꯁꯅ ꯄꯤꯒꯗꯕ ꯄꯨꯝꯅꯃꯛ', 'g3.p.avail': 'ꯌꯥꯕ ꯀ꯭ꯔꯦꯗꯤꯠ', 'g3.p.cf': 'ꯃꯇꯨꯡꯒꯤ ꯃꯇꯝꯒꯤꯗꯃꯛ ꯂꯦꯃꯍꯧꯔꯕ ꯀ꯭ꯔꯦꯗꯤꯠ',
  'g3.note': 'CGST ꯑꯦꯛꯇꯀꯤ ꯗꯥꯔꯥ 49 ꯑꯃꯁꯨꯡ ꯅꯤꯌꯃ 88A ꯃꯇꯨꯡ ꯏꯟꯅ ꯁꯦꯇ-ꯑꯣꯐ: ꯑꯍꯥꯅꯕꯗ IGST ꯀ꯭ꯔꯦꯗꯤꯠ ꯁꯤꯖꯤꯟꯅꯩ, ꯃꯇꯨꯡꯗ CGST ꯑꯃꯁꯨꯡ SGST/UTGST ꯀ꯭ꯔꯦꯗꯤꯠ; CGST ꯑꯃꯁꯨꯡ SGST ꯀ꯭ꯔꯦꯗꯤꯠ ꯑꯃꯅ ꯑꯃꯕꯨ ꯀꯩꯗꯧꯉꯩꯗꯁꯨ ꯁꯤꯖꯤꯟꯅꯦ; ꯔꯤꯚꯔꯁ ꯆꯥꯔꯖ ꯇꯦꯛꯁ ꯀꯦꯁꯅ ꯄꯤꯔꯤ꯫ ꯅꯍꯥꯛꯅ ꯐꯥꯏꯜ ꯇꯧꯕꯗ ꯄꯣꯔꯇꯂꯅ ꯑꯔꯣꯏꯕ ꯁꯦꯇ-ꯑꯣꯐ ꯇꯧꯏ꯫',
  'g3.w.zr': 'ꯕꯤꯜ {no} ꯑꯁꯤ ꯑꯦꯛꯁꯄꯣꯔꯠ ꯅꯠꯇ꯭ꯔꯒ SEZ ꯕꯤꯜ ꯑꯣꯏꯅ CGST/SGST ꯎꯠꯂꯤ꯫ ꯖꯤꯔꯣ ꯔꯦꯇꯦꯗ ꯁꯞꯂꯥꯏꯗ IGST ꯈꯛꯇꯅ ꯂꯩ꯫', 'g3.w.rcmv': 'ꯚꯥꯎꯆꯔ {no}: ꯔꯤꯚꯔꯁ ꯆꯥꯔꯖ ꯇꯦꯛꯁ CGST + SGST ꯑꯣꯏꯅ ꯂꯧꯈ꯭ꯔꯦ꯫ ꯁꯞꯂꯥꯌꯔ ꯁ꯭ꯇꯦꯠ ꯑꯇꯣꯞꯄꯗ ꯂꯩꯔꯕꯗ (IGST) ꯕꯣꯛꯁꯁꯤꯡ ꯍꯣꯡꯗꯣꯛꯇꯨꯅ ꯇꯧꯕꯤꯌꯨ꯫',
  'g3.w.nogstin': '{p} ꯗꯒꯤ ꯄꯔꯆꯦꯖ ꯕꯤꯜ {no} ꯗ ꯁꯞꯂꯥꯌꯔꯒꯤ ꯑꯣꯏꯕ GSTIN ꯂꯩꯇꯕꯅ ꯃꯁꯤꯒꯤ ITC GSTR-2B ꯗ ꯎꯠꯂꯣꯏ꯫', 'g3.w.2b': 'ꯕꯣꯛꯁ 4(A)(5) ꯒꯤ ITC ꯑꯁꯤ ꯅꯍꯥꯛꯀꯤ ꯁꯦꯚ ꯇꯧꯔꯕ ꯄꯔꯆꯦꯖ ꯕꯤꯜ ꯑꯃꯁꯨꯡ ꯈꯥꯏꯅꯕꯗꯒꯤ ꯂꯥꯀꯏ꯫ ꯅꯍꯥꯛꯀꯤ GSTR-2B ꯅ ꯎꯠꯂꯤꯕ ꯈꯛꯇꯅ ꯀ꯭ꯂꯦꯝ ꯇꯧꯕꯤꯌꯨ; ꯃꯗꯨ ꯑꯍꯟꯅ ꯅꯠꯇ꯭ꯔꯒ GSTR-2B ꯒꯤ ꯃꯁꯤꯡ ꯇꯥꯏꯞ ꯇꯧꯕꯤꯌꯨ꯫',
  'g3.w.neg': 'ꯌꯥꯕ ꯀ꯭ꯔꯦꯗꯤꯠ ꯖꯤꯔꯣꯗꯒꯤ ꯍꯟꯅ ꯃꯃꯤ: ꯍꯟꯗꯣꯛꯂꯕ ꯀ꯭ꯔꯦꯗꯤꯠ ꯑꯁꯤ ꯀ꯭ꯔꯦꯗꯤꯠꯗꯒꯤ ꯍꯦꯟꯅ ꯃꯤ꯫ ꯇꯣꯉꯥꯟꯅꯕ ꯑꯗꯨ ꯀꯦꯁꯅ ꯄꯤꯒꯗꯕꯅꯤ; ꯅꯍꯥꯛꯀꯤ ꯑꯦꯀꯥꯎꯟꯇꯦꯟꯇꯇ ꯍꯪꯕꯤꯌꯨ꯫',
  /* gstr2b */
  'nav.gstr2b': 'GSTR-2B ꯃꯦꯆꯔ', 'f.gstr2b': 'GSTR-2B ꯑꯃꯁꯨꯡ ꯄꯔꯆꯦꯖ ꯕꯤꯜ ꯃꯦꯆꯔ',
  'g2.file': 'ꯅꯍꯥꯛꯀꯤ GSTR-2B ꯐꯥꯏꯜ ꯍꯥꯡꯗꯣꯛꯄꯤꯌꯨ (JSON ꯅꯠꯇ꯭ꯔꯒ Excel)', 'g2.drop': 'ꯅꯠꯇ꯭ꯔꯒ ꯐꯥꯏꯜ ꯑꯗꯨ ꯃꯐꯝ ꯑꯁꯤꯗ ꯊꯥꯎ', 'g2.privacy': 'ꯐꯥꯏꯜ ꯑꯗꯨ ꯕ꯭ꯔꯥꯎꯖꯔ ꯑꯁꯤꯗ ꯈꯛꯇꯅ ꯄꯥꯕꯅꯤ꯫ ꯀꯅꯥꯒꯨꯝꯕ ꯃꯐꯝꯗ ꯑꯄꯂꯣꯗ ꯇꯧꯗꯦ꯫',
  'g2.from': 'ꯄꯔꯆꯦꯖ ꯕꯤꯜꯁꯤꯡ ꯃꯇꯝ', 'g2.to': 'ꯐꯥꯑꯣꯕ', 'g2.tol': 'ꯌꯥꯕꯤꯒꯗꯕ ꯇꯣꯉꯥꯟꯅꯕ', 'g2.reg': 'GST ꯃꯦꯆꯤꯡ ꯇꯨꯂꯒꯤꯗꯃꯛ ꯄꯔꯆꯦꯖ ꯔꯦꯖꯤꯁ꯭ꯇꯔ', 'g2.regh': 'ꯇꯥꯡ ꯑꯁꯤꯁꯤꯡꯒꯤ ꯅꯍꯥꯛꯀꯤ ꯄꯔꯆꯦꯖ ꯕꯤꯜꯁꯤꯡꯗꯒꯤ ꯁꯦꯝꯕ, ꯄꯣꯔꯇꯂꯒꯤ Matching Offline Tool ꯂꯦꯑꯥꯎꯇꯇ ꯂꯩꯕ Excel ꯑꯃꯅꯤ꯫',
  'g2.loaded': 'ꯕ꯭ꯔꯥꯎꯖꯔ ꯑꯁꯤꯒꯤ ꯗꯦꯇꯥ ꯍꯣꯝꯗ ꯄꯔꯆꯦꯖ ꯕꯤꯜ {n} ꯐꯪꯈꯤ꯫', 'g2.reading': '{f} ꯄꯥꯔꯤ…', 'g2.read': 'GSTR-2B ꯄꯥꯈꯤ: ꯗꯣꯀꯨꯃꯦꯟꯠ {n}, GSTIN {g}, ꯄꯤꯔꯤꯌꯗ {p}꯫',
